-- Centro operativo del Departamento Financiero: cuentas por pagar, tesorería, contabilidad y cierres.
create table if not exists public.financial_bank_accounts(id uuid primary key default gen_random_uuid(),bank_name text not null,account_number_masked text not null,account_type text not null default 'Corriente',currency text not null default 'DOP',opening_balance numeric(18,2) not null default 0,current_balance numeric(18,2) not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.financial_payment_requests(id uuid primary key default gen_random_uuid(),code text not null unique,source_type text not null default 'OTRO',source_id uuid,project_id uuid references public.technical_projects(id),supplier text not null,concept text not null,invoice_number text not null default '',budget_account text not null default '',gross_amount numeric(18,2) not null check(gross_amount>=0),retention_amount numeric(18,2) not null default 0,net_amount numeric(18,2) generated always as (gross_amount-retention_amount) stored,due_date date,status text not null default 'REGISTRADA',payment_reference text not null default '',requested_by uuid references public.app_users(id),reviewed_by uuid references public.app_users(id),released_by uuid references public.app_users(id),paid_by uuid references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.financial_treasury_movements(id uuid primary key default gen_random_uuid(),bank_account_id uuid references public.financial_bank_accounts(id),payment_request_id uuid references public.financial_payment_requests(id),movement_date date not null default current_date,movement_type text not null check(movement_type in('INGRESO','EGRESO','TRANSFERENCIA','AJUSTE')),reference text not null,description text not null,amount numeric(18,2) not null check(amount>=0),status text not null default 'REGISTRADO',created_by uuid references public.app_users(id),created_at timestamptz not null default now());
create table if not exists public.financial_bank_reconciliations(id uuid primary key default gen_random_uuid(),bank_account_id uuid not null references public.financial_bank_accounts(id),period_year integer not null,period_month integer not null check(period_month between 1 and 12),book_balance numeric(18,2) not null,bank_balance numeric(18,2) not null,outstanding_deposits numeric(18,2) not null default 0,outstanding_checks numeric(18,2) not null default 0,adjustments numeric(18,2) not null default 0,difference numeric(18,2) not null default 0,status text not null default 'BORRADOR',prepared_by uuid references public.app_users(id),approved_by uuid references public.app_users(id),created_at timestamptz not null default now(),unique(bank_account_id,period_year,period_month));
create table if not exists public.financial_accounting_entries(id uuid primary key default gen_random_uuid(),entry_number text not null unique,entry_date date not null default current_date,description text not null,debit_account text not null,credit_account text not null,amount numeric(18,2) not null check(amount>0),source_type text not null default 'MANUAL',source_id uuid,status text not null default 'BORRADOR',created_by uuid references public.app_users(id),approved_by uuid references public.app_users(id),created_at timestamptz not null default now());
create table if not exists public.financial_period_closures(id uuid primary key default gen_random_uuid(),period_year integer not null,period_month integer not null check(period_month between 1 and 12),closure_type text not null default 'MENSUAL',status text not null default 'ABIERTO',observation text not null default '',closed_by uuid references public.app_users(id),closed_at timestamptz,created_at timestamptz not null default now(),unique(period_year,period_month,closure_type));
do $$declare t text;begin foreach t in array array['financial_bank_accounts','financial_payment_requests','financial_treasury_movements','financial_bank_reconciliations','financial_accounting_entries','financial_period_closures'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end$$;
create sequence if not exists public.financial_direction_seq start 1;

create or replace function public.list_financial_direction(p_token text,p_year integer default null)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare u public.app_users;v_year integer:=coalesce(p_year,extract(year from current_date)::integer);result jsonb;
begin
 u:=public.hr_authenticated_user(p_token);if u.id is null or (u.role<>'Administrador' and not coalesce((u.permissions->>'ver_direccion_financiera')::boolean,false)) then return jsonb_build_object('success',false,'error','No autorizado.');end if;
 select jsonb_build_object('success',true,'year',v_year,
  'payments',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from(select r.*,p.work_name,p.snip_code from public.financial_payment_requests r left join public.technical_projects p on p.id=r.project_id where extract(year from r.created_at)=v_year)x),
  'accounts',(select coalesce(jsonb_agg(to_jsonb(a) order by bank_name),'[]'::jsonb) from public.financial_bank_accounts a where a.active),
  'treasury',(select coalesce(jsonb_agg(to_jsonb(x) order by movement_date desc,created_at desc),'[]'::jsonb) from(select m.*,a.bank_name,a.account_number_masked from public.financial_treasury_movements m left join public.financial_bank_accounts a on a.id=m.bank_account_id where extract(year from m.movement_date)=v_year)x),
  'reconciliations',(select coalesce(jsonb_agg(to_jsonb(x) order by period_year desc,period_month desc),'[]'::jsonb) from(select r.*,a.bank_name,a.account_number_masked from public.financial_bank_reconciliations r join public.financial_bank_accounts a on a.id=r.bank_account_id where r.period_year=v_year)x),
  'entries',(select coalesce(jsonb_agg(to_jsonb(e) order by entry_date desc),'[]'::jsonb) from public.financial_accounting_entries e where extract(year from e.entry_date)=v_year),
  'closures',(select coalesce(jsonb_agg(to_jsonb(c) order by period_month desc),'[]'::jsonb) from public.financial_period_closures c where c.period_year=v_year),
  'projects',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'work_name',p.work_name,'snip_code',p.snip_code,'supplier',p.supplier_contractor,'budget_account',p.budget_account) order by p.work_name),'[]'::jsonb) from public.technical_projects p where p.project_year=v_year),
  'metrics',jsonb_build_object('pendingPayments',(select count(*) from public.financial_payment_requests where status not in('PAGADA','RECHAZADA') and extract(year from created_at)=v_year),'pendingAmount',(select coalesce(sum(net_amount),0) from public.financial_payment_requests where status not in('PAGADA','RECHAZADA') and extract(year from created_at)=v_year),'paidAmount',(select coalesce(sum(net_amount),0) from public.financial_payment_requests where status='PAGADA' and extract(year from created_at)=v_year),'treasuryBalance',(select coalesce(sum(current_balance),0) from public.financial_bank_accounts where active),'unreconciled',(select count(*) from public.financial_bank_reconciliations where period_year=v_year and (status<>'APROBADA' or abs(difference)>0.01)),'draftEntries',(select count(*) from public.financial_accounting_entries where status='BORRADOR' and extract(year from entry_date)=v_year),'projectPaid',(select coalesce(sum(total_paid),0) from public.technical_projects where project_year=v_year),'inRelease',(select coalesce(sum(amount),0) from public.project_measurements m join public.technical_projects p on p.id=m.project_id where p.project_year=v_year and m.status='Libramiento')+coalesce((select coalesce(sum(a.amount) filter(where a.status='Libramiento'),0)+coalesce(sum(a.advance_amount) filter(where a.advance_status='Libramiento'),0) from public.financial_assets a join public.technical_projects p on p.id=a.project_id where p.project_year=v_year),0))
 ) into result;return result;
end$$;

create or replace function public.manage_financial_direction(p_token text,p_action text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare u public.app_users;new_id uuid;code text;can_manage boolean;current_status text;target_status text;
begin
 u:=public.hr_authenticated_user(p_token);can_manage:=u.role='Administrador' or coalesce((u.permissions->>'gestionar_direccion_financiera')::boolean,false);if u.id is null or not can_manage then return jsonb_build_object('success',false,'error','No autorizado.');end if;
 if p_action='CREATE_PAYMENT' then code='LIB-'||extract(year from current_date)::int||'-'||lpad(nextval('public.financial_direction_seq')::text,6,'0');insert into public.financial_payment_requests(code,source_type,source_id,project_id,supplier,concept,invoice_number,budget_account,gross_amount,retention_amount,due_date,requested_by) values(code,coalesce(p_data->>'source_type','OTRO'),nullif(p_data->>'source_id','')::uuid,nullif(p_data->>'project_id','')::uuid,p_data->>'supplier',p_data->>'concept',coalesce(p_data->>'invoice_number',''),coalesce(p_data->>'budget_account',''),coalesce(nullif(p_data->>'gross_amount','')::numeric,0),coalesce(nullif(p_data->>'retention_amount','')::numeric,0),nullif(p_data->>'due_date','')::date,u.id) returning id into new_id;
 elsif p_action='ADVANCE_PAYMENT' then select status into current_status from public.financial_payment_requests where id=(p_data->>'id')::uuid for update;target_status:=case current_status when 'REGISTRADA' then 'REVISADA' when 'REVISADA' then 'LIBRAMIENTO' when 'LIBRAMIENTO' then 'PAGADA' else null end;if target_status is null then return jsonb_build_object('success',false,'error','La solicitud no puede avanzar desde su estado actual.');end if;if u.role<>'Administrador' and target_status='PAGADA' and not coalesce((u.permissions->>'pagar_direccion_financiera')::boolean,false) then return jsonb_build_object('success',false,'error','No posee permiso para registrar pagos.');end if;update public.financial_payment_requests set status=target_status,reviewed_by=case when target_status='REVISADA' then u.id else reviewed_by end,released_by=case when target_status='LIBRAMIENTO' then u.id else released_by end,paid_by=case when target_status='PAGADA' then u.id else paid_by end,payment_reference=case when target_status='PAGADA' then coalesce(p_data->>'payment_reference','') else payment_reference end,updated_at=now() where id=(p_data->>'id')::uuid returning id into new_id;
 elsif p_action='CREATE_BANK' then insert into public.financial_bank_accounts(bank_name,account_number_masked,account_type,currency,opening_balance,current_balance) values(p_data->>'bank_name',p_data->>'account_number_masked',coalesce(p_data->>'account_type','Corriente'),coalesce(p_data->>'currency','DOP'),coalesce(nullif(p_data->>'opening_balance','')::numeric,0),coalesce(nullif(p_data->>'opening_balance','')::numeric,0)) returning id into new_id;
 elsif p_action='CREATE_TREASURY' then insert into public.financial_treasury_movements(bank_account_id,payment_request_id,movement_date,movement_type,reference,description,amount,created_by) values(nullif(p_data->>'bank_account_id','')::uuid,nullif(p_data->>'payment_request_id','')::uuid,coalesce(nullif(p_data->>'movement_date','')::date,current_date),p_data->>'movement_type',p_data->>'reference',p_data->>'description',coalesce(nullif(p_data->>'amount','')::numeric,0),u.id) returning id into new_id;update public.financial_bank_accounts set current_balance=current_balance+case when p_data->>'movement_type'='INGRESO' then coalesce(nullif(p_data->>'amount','')::numeric,0) else -coalesce(nullif(p_data->>'amount','')::numeric,0) end where id=nullif(p_data->>'bank_account_id','')::uuid;
 elsif p_action='CREATE_RECONCILIATION' then insert into public.financial_bank_reconciliations(bank_account_id,period_year,period_month,book_balance,bank_balance,outstanding_deposits,outstanding_checks,adjustments,difference,prepared_by) values((p_data->>'bank_account_id')::uuid,(p_data->>'period_year')::integer,(p_data->>'period_month')::integer,(p_data->>'book_balance')::numeric,(p_data->>'bank_balance')::numeric,coalesce(nullif(p_data->>'outstanding_deposits','')::numeric,0),coalesce(nullif(p_data->>'outstanding_checks','')::numeric,0),coalesce(nullif(p_data->>'adjustments','')::numeric,0),(p_data->>'bank_balance')::numeric+coalesce(nullif(p_data->>'outstanding_deposits','')::numeric,0)-coalesce(nullif(p_data->>'outstanding_checks','')::numeric,0)+coalesce(nullif(p_data->>'adjustments','')::numeric,0)-(p_data->>'book_balance')::numeric,u.id) returning id into new_id;
 elsif p_action='CREATE_ENTRY' then code='ASI-'||extract(year from current_date)::int||'-'||lpad(nextval('public.financial_direction_seq')::text,6,'0');insert into public.financial_accounting_entries(entry_number,entry_date,description,debit_account,credit_account,amount,source_type,created_by) values(code,coalesce(nullif(p_data->>'entry_date','')::date,current_date),p_data->>'description',p_data->>'debit_account',p_data->>'credit_account',(p_data->>'amount')::numeric,coalesce(p_data->>'source_type','MANUAL'),u.id) returning id into new_id;
 elsif p_action='CLOSE_PERIOD' then if u.role<>'Administrador' and not coalesce((u.permissions->>'cerrar_periodo_financiero')::boolean,false) then return jsonb_build_object('success',false,'error','No posee permiso para cerrar períodos.');end if;insert into public.financial_period_closures(period_year,period_month,closure_type,status,observation,closed_by,closed_at) values((p_data->>'period_year')::integer,(p_data->>'period_month')::integer,coalesce(p_data->>'closure_type','MENSUAL'),'CERRADO',coalesce(p_data->>'observation',''),u.id,now()) on conflict(period_year,period_month,closure_type) do update set status='CERRADO',observation=excluded.observation,closed_by=u.id,closed_at=now() returning id into new_id;
 else return jsonb_build_object('success',false,'error','Acción financiera no reconocida.');end if;return jsonb_build_object('success',true,'id',new_id,'code',code,'status',target_status);
exception when others then return jsonb_build_object('success',false,'error',sqlerrm);end$$;
grant execute on function public.list_financial_direction(text,integer),public.manage_financial_direction(text,text,jsonb) to anon,authenticated;
